#!/usr/bin/env python3
"""Remove events from the strfry database that kind-policy.py would reject.

The write policy only gates new events; everything stored before it was
tightened stays in LMDB until deleted here.  This script applies the exact
same rule (it imports is_allowed() from kind-policy.py) to a dump of the
database and prepares `strfry delete` commands for the events that fail it.

Run ON THE RELAY HOST, as the user that owns the database (see
strfry.service), with the relay running or stopped:

    cd /etc/strfry                     # or wherever both scripts live
    strfry export | ./cleanup-rejected.py plan --out /var/tmp/cleanup
    /var/tmp/cleanup/delete.sh --dry-run   # prints what strfry would delete, per chunk
    /var/tmp/cleanup/delete.sh             # deletes; safe to re-run, already-deleted ids are skipped
    strfry export | ./cleanup-rejected.py plan --out /var/tmp/cleanup-check   # expect "nothing to delete"

`plan` prints a per-kind keep/drop table and writes into --out:

    drop.events.jsonl       full backup of every event to be deleted
                            (undo: strfry import < drop.events.jsonl)
    drop.ids.txt            one event id per line
    drop.review.txt         what the drop set contains, for a human to check before
                            deleting: every pubkey that has WalletScrutiny events
                            AND loses events (with each lost event listed), dropped
                            deletions that point at a kept event (expected: none),
                            and per kind the top authors and client tags being dropped
    delete-NNNN.filter.json strfry filters, CHUNK ids each
    delete.sh               the strfry commands

Options:
    --kinds 5,30301         only consider these kinds (default: every kind in the dump)
    --policy PATH           kind-policy.py to load (default: next to this script,
                            then /etc/strfry/kind-policy.py)
    --no-backup             skip drop.events.jsonl (it is as large as the data, ~0.7 GB
                            for the 2026-10 census)

Why not from a remote machine: a NIP-09 deletion request is honoured only for
the author's own events and strfry has no remote admin API, so deletion has to
touch the LMDB on the host.  The input is plain JSONL (one event per line), so
a remote `nak req ... | ./cleanup-rejected.py plan` works for counting, but the
resulting delete.sh still has to run on the host.
"""

import argparse
import collections
import importlib.util
import json
import os
import stat
import sys

# Ids per `strfry delete --filter` call.  A 1,500-id filter is ~100 KB, under
# Linux's 128 KB limit for a single command-line argument.
CHUNK = 1500

HERE = os.path.dirname(os.path.abspath(__file__))
POLICY_CANDIDATES = [os.path.join(HERE, "kind-policy.py"), "/etc/strfry/kind-policy.py"]

DELETE_SH_HEAD = """#!/bin/sh
# Generated by cleanup-rejected.py; run on the relay host as the strfry user.
# Set STRFRY if the binary or config is not the default, e.g.
#   STRFRY='/usr/local/bin/strfry --config /etc/strfry/strfry.conf' ./delete.sh --dry-run
# Pass --dry-run as the first argument to only count.
set -eu
DRY="${1:-}"
STRFRY="${STRFRY:-strfry}"
cd "$(dirname "$0")"
"""


def load_policy(path):
    spec = importlib.util.spec_from_file_location("kind_policy", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    if not hasattr(module, "is_allowed"):
        sys.exit(f"{path} has no is_allowed(); it is older than this script")
    return module


def read_events(stream, kinds):
    """Yield (event, size_in_bytes) for every JSON line that is an event."""
    for line in stream:
        line = line.strip()
        if not line:
            continue
        try:
            event = json.loads(line)
        except json.JSONDecodeError:
            print(f"skipping unparsable line: {line[:80]}", file=sys.stderr)
            continue
        if not isinstance(event, dict) or "id" not in event or "kind" not in event:
            continue
        if kinds and event["kind"] not in kinds:
            continue
        yield event, len(line)


def print_table(stats):
    print(f"{'kind':>6} {'keep':>8} {'drop':>8} {'drop MB':>8}")
    tk = td = tb = 0
    for kind in sorted(stats):
        keep, drop, drop_bytes = stats[kind]
        tk, td, tb = tk + keep, td + drop, tb + drop_bytes
        print(f"{kind:6d} {keep:8d} {drop:8d} {drop_bytes / 1e6:8.1f}")
    print(f"{'total':>6} {tk:8d} {td:8d} {tb / 1e6:8.1f}")


def label(event):
    """One line a human can recognise an event by."""
    tags = event.get("tags", [])
    if event.get("kind") == 5:
        return "deletes " + " ".join(f"{t[0]}={t[1][:20]}" for t in tags if len(t) > 1 and t[0] in ("e", "a", "k"))
    for name in ("title", "alt", "name", "d"):
        for t in tags:
            if len(t) > 1 and t[0] == name and t[1]:
                return f"{name}={t[1][:60]!r}"
    return repr(event.get("content", "")[:60])


def when(event):
    import datetime
    return datetime.datetime.utcfromtimestamp(event.get("created_at", 0)).strftime("%Y-%m-%d")


class Review:
    """Collect what is needed for drop.review.txt without holding the events."""

    TOP = 5

    def __init__(self):
        self.kept_ids = set()
        self.kept_addr = set()
        self.ws_authors = set()                    # pubkeys with a kept event of a tagged kind
        self.drop_author = collections.Counter()   # (pubkey, kind) -> n
        self.drop_client = collections.Counter()   # (kind, client) -> n

    def kept(self, event):
        self.kept_ids.add(event["id"])
        if event["kind"] != 5:
            self.ws_authors.add(event["pubkey"])
        for t in event.get("tags", []):
            if len(t) > 1 and t[0] == "d":
                self.kept_addr.add(f"{event['kind']}:{event['pubkey']}:{t[1]}")
                break

    def dropped(self, event):
        self.drop_author[(event["pubkey"], event["kind"])] += 1
        client = next((t[1] for t in event.get("tags", []) if len(t) > 1 and t[0] == "client"), "")
        self.drop_client[(event["kind"], client)] += 1

    def write(self, path, backup_path):
        losers = sorted({p for p, _ in self.drop_author if p in self.ws_authors})
        out = [f"{len(losers)} pubkeys with WalletScrutiny events also lose events "
               f"({sum(n for (p, _), n in self.drop_author.items() if p in losers)} events):"]
        for p in losers:
            kinds = {k: n for (q, k), n in self.drop_author.items() if q == p}
            out.append(f"  {p}  " + ", ".join(f"kind {k}: {n}" for k, n in sorted(kinds.items())))
        if backup_path:
            detail, pointing = collections.defaultdict(list), []
            with open(backup_path) as f:
                for line in f:
                    ev = json.loads(line)
                    if ev["pubkey"] in losers:
                        detail[ev["pubkey"]].append(f"    {when(ev)} kind {ev['kind']:5d} {ev['id'][:12]}  {label(ev)}")
                    if ev["kind"] == 5:
                        refs = {t[1] for t in ev.get("tags", []) if len(t) > 1 and t[0] in ("e", "a")}
                        if refs & self.kept_ids or refs & self.kept_addr:
                            pointing.append(f"  {when(ev)} {ev['id']}  {label(ev)}")
            for p in losers:
                out.append(f"\n  {p}")
                out.extend(sorted(detail[p]))
            out.append(f"\n{len(pointing)} dropped deletions point at a kept event (expected 0):")
            out.extend(pointing)
        else:
            out.append("\n(--no-backup: per-event detail and the deletion cross-check need drop.events.jsonl)")
        for kind in sorted({k for _, k in self.drop_author}):
            out.append(f"\nkind {kind}: top dropped authors")
            for (p, k), n in sorted(((pk, n) for pk, n in self.drop_author.items() if pk[1] == kind),
                                    key=lambda x: -x[1])[:self.TOP]:
                out.append(f"  {n:8d}  {p}")
            out.append(f"kind {kind}: top dropped client tags")
            for (k, c), n in sorted(((kc, n) for kc, n in self.drop_client.items() if kc[0] == kind),
                                    key=lambda x: -x[1])[:self.TOP]:
                out.append(f"  {n:8d}  {c or '(none)'}")
        with open(path, "w") as f:
            f.write("\n".join(out) + "\n")
        print(f"review: {out[0]}  details in {path}")


def cmd_plan(args):
    policy = load_policy(args.policy)
    kinds = {int(k) for k in args.kinds.split(",")} if args.kinds else None

    os.makedirs(args.out, exist_ok=True)
    stats = collections.defaultdict(lambda: [0, 0, 0])   # kind -> [keep, drop, drop bytes]
    ids = []
    review = Review()
    backup = None if args.no_backup else open(os.path.join(args.out, "drop.events.jsonl"), "w")
    try:
        for event, size in read_events(sys.stdin, kinds):
            entry = stats[event["kind"]]
            if policy.is_allowed(event):
                entry[0] += 1
                review.kept(event)
                continue
            entry[1] += 1
            entry[2] += size
            ids.append(event["id"])
            review.dropped(event)
            if backup:
                backup.write(json.dumps(event, separators=(",", ":")) + "\n")
    finally:
        if backup:
            backup.close()

    print_table(stats)
    if not ids:
        print("nothing to delete")
        if backup:
            os.remove(backup.name)
        return

    ids.sort()
    with open(os.path.join(args.out, "drop.ids.txt"), "w") as f:
        f.write("\n".join(ids) + "\n")
    review.write(os.path.join(args.out, "drop.review.txt"), None if args.no_backup else backup.name)

    script = [DELETE_SH_HEAD]
    for n, start in enumerate(range(0, len(ids), CHUNK)):
        name = f"delete-{n:04d}.filter.json"
        with open(os.path.join(args.out, name), "w") as f:
            json.dump({"ids": ids[start:start + CHUNK]}, f, separators=(",", ":"))
        script.append(f'$STRFRY delete --filter "$(cat {name})" $DRY')
    path = os.path.join(args.out, "delete.sh")
    with open(path, "w") as f:
        f.write("\n".join(script) + "\n")
    os.chmod(path, os.stat(path).st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)

    print(f"\nwrote {len(ids)} ids in {n + 1} filter files"
          f"{'' if args.no_backup else ' plus drop.events.jsonl backup'} to {args.out}/")
    print(f"next: {path} --dry-run, then {path}")


def main():
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("command", choices=["plan"])
    parser.add_argument("--out", default="strfry-cleanup")
    parser.add_argument("--kinds", default="")
    parser.add_argument("--policy", default=next((p for p in POLICY_CANDIDATES if os.path.exists(p)),
                                                 POLICY_CANDIDATES[0]))
    parser.add_argument("--no-backup", action="store_true")
    args = parser.parse_args()
    if not os.path.exists(args.policy):
        sys.exit(f"kind-policy.py not found (tried {', '.join(POLICY_CANDIDATES)}); pass --policy")
    cmd_plan(args)


if __name__ == "__main__":
    main()
